SELECT conversion_event_date_utc, COALESCE(ad_product_type, 'amazon_dsp') AS ad_product_type, CASE WHEN COALESCE(ad_product_type, 'amazon_dsp') IN ('sponsored_products', 'sponsored_brands') THEN 'search' WHEN COALESCE(ad_product_type, 'amazon_dsp') = 'sponsored_television' THEN 'video' ELSE 'display' END AS channel_group_key, campaign_id_string, tracked_asin, conversion_event_marketplace_name, SUM(conversions) AS conversions, SUM(purchases) AS purchases, SUM(total_purchases) AS total_purchases, SUM(product_sales) AS product_sales, SUM(total_product_sales) AS total_product_sales, SUM(new_to_brand_product_sales) AS new_to_brand_product_sales, purchase_currency, SUM(units_sold) AS units_sold, SUM(total_units_sold) AS total_units_sold, SUM(new_to_brand_purchases) AS new_to_brand_purchases, SUM(new_to_brand_total_purchases) AS new_to_brand_total_purchases, BUILT_IN_PARAMETER('TIME_WINDOW_START') AS time_window_start, BUILT_IN_PARAMETER('TIME_WINDOW_END') AS time_window_end FROM amazon_attributed_events_by_conversion_time WHERE conversion_event_category = 'purchase' AND tracked_asin IS NOT NULL GROUP BY conversion_event_date_utc, COALESCE(ad_product_type, 'amazon_dsp'), CASE WHEN COALESCE(ad_product_type, 'amazon_dsp') IN ('sponsored_products', 'sponsored_brands') THEN 'search' WHEN COALESCE(ad_product_type, 'amazon_dsp') = 'sponsored_television' THEN 'video' ELSE 'display' END, campaign_id_string, tracked_asin, conversion_event_marketplace_name, purchase_currency
